dashboard.definition:
{
    "title": "Daily state of health",
    "description": "Engineering view of the latest DH Daily SoH report (07:00, index=data_health source=dh:soh) plus the live unregistered list (spec §8.4).",
    "inputs": {},
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "-8d",
                        "latest": "+1d"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_soh": {
            "type": "ds.search",
            "name": "Latest daily report (dh:soh)",
            "options": {
                "query": "search index=data_health source=\"dh:soh\" sourcetype=stash earliest=-8d latest=+1d | eval report_time=tonumber(report_time) | eventstats max(report_time) as dh_latest | where report_time==dh_latest | table report_time section item value start end open outages open_outages mttr_secs version last_seen day min_ratio reason ticket set_by"
            }
        },
        "ds_when": {
            "type": "ds.chain",
            "name": "Report time",
            "options": {
                "extend": "ds_soh",
                "query": "| stats max(report_time) as t | eval report=if(isnull(t), \"no report yet (DH Daily SoH report runs at 07:00)\", strftime(t, \"%Y-%m-%d %H:%M\")) | table report"
            }
        },
        "ds_mttr": {
            "type": "ds.chain",
            "name": "MTTR",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"mttr\" | eval mttr=if(isnull(value) OR value==\"\", \"-\", tostring(tonumber(value), \"duration\")) | table mttr outages open_outages"
            }
        },
        "ds_outages": {
            "type": "ds.chain",
            "name": "Outages",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"outage\" | eval start=strftime(tonumber(start), \"%Y-%m-%d %H:%M\"), end=if(tonumber(open)==1, \"still open\", strftime(tonumber(end), \"%Y-%m-%d %H:%M\")), duration=tostring(tonumber(value), \"duration\") | sort 0 -value | table item start end duration | rename item AS entity_id | `dh_ui_headers`"
            }
        },
        "ds_flapping": {
            "type": "ds.chain",
            "name": "Flapping",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"flapping\" | sort 0 -value | table item value | rename item AS entity_id, value AS transitions_24h | `dh_ui_headers`"
            }
        },
        "ds_never": {
            "type": "ds.chain",
            "name": "Never seen and invalid profiles",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"never_seen\" OR section==\"invalid_profile\" | eval detail=if(section==\"never_seen\", \"expected since \".strftime(tonumber(value), \"%Y-%m-%d %H:%M\"), value) | eval section=case(section==\"never_seen\", \"never arrived\", section==\"invalid_profile\", \"unknown profile\", true(), section) | table section item detail | rename item AS entity_id | `dh_ui_headers`"
            }
        },
        "ds_unreg": {
            "type": "ds.search",
            "name": "Unregistered (live)",
            "options": {
                "query": "| `dh_ui_unregistered(dh_expected, dh_state_fast, dh_state_slow, dh_baseline, now())` | `dh_ui_headers`"
            }
        },
        "ds_fwd": {
            "type": "ds.chain",
            "name": "Forwarders",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"fwd_version\" OR section==\"fwd_disconnected\" | eval last_seen=strftime(tonumber(last_seen), \"%Y-%m-%d %H:%M\") | eval section=case(section==\"fwd_version\", \"wrong version\", section==\"fwd_disconnected\", \"disconnected\", true(), section) | table section item version last_seen | rename item AS host | `dh_ui_headers`"
            }
        },
        "ds_lag": {
            "type": "ds.chain",
            "name": "Lag p95",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"lag\" | sort 0 -value | eval day=strftime(tonumber(day), \"%Y-%m-%d\") | table item value day | rename item AS entity_id, value AS lag_p95_secs | `dh_ui_headers`"
            }
        },
        "ds_volume": {
            "type": "ds.chain",
            "name": "Volume flags",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"volume\" | sort 0 -value | table item value min_ratio | rename item AS entity_id, value AS flagged_hours | `dh_ui_headers`"
            }
        },
        "ds_lic_pct": {
            "type": "ds.chain",
            "name": "Licence usage",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"licence\" AND item==\"usage_pct\" | eval usage=value.\"%\" | table usage"
            }
        },
        "ds_lic_days": {
            "type": "ds.chain",
            "name": "Licence expiry",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"licence\" AND item==\"expires_days\" | table value"
            }
        },
        "ds_skipped": {
            "type": "ds.chain",
            "name": "Skipped searches",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"skipped\" | sort 0 -value | table item value | rename item AS search, value AS skipped_24h | `dh_ui_headers`"
            }
        },
        "ds_mutes": {
            "type": "ds.chain",
            "name": "Mutes",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"mute_expiring\" OR section==\"mute_active\" | eval until=strftime(tonumber(value), \"%Y-%m-%d %H:%M\") | eval section=case(section==\"mute_active\", \"active\", section==\"mute_expiring\", \"ends within 24 h\", true(), section) | table section item until reason ticket set_by | rename item AS entity_id | `dh_ui_headers`"
            }
        }
    },
    "visualizations": {
        "viz_when": {
            "type": "splunk.singlevalue",
            "title": "Report time",
            "dataSources": {
                "primary": "ds_when"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"report\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "When the daily report was made (07:00 each day). Guide: docs/data-health/dashboards.md, Daily state of health > Report time"
        },
        "viz_mttr": {
            "type": "splunk.singlevalue",
            "title": "Mean time to recover (24 h)",
            "dataSources": {
                "primary": "ds_mttr"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"mttr\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How long an outage lasted on average. Guide: docs/data-health/dashboards.md, Daily state of health > Mean time to recover (24 h)"
        },
        "viz_outages_n": {
            "type": "splunk.singlevalue",
            "title": "Outages (24 h)",
            "dataSources": {
                "primary": "ds_mttr"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"outages\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How many times data stopped in the last 24 h. Guide: docs/data-health/dashboards.md, Daily state of health > Outages (24 h)"
        },
        "viz_open_n": {
            "type": "splunk.singlevalue",
            "title": "Outages still open",
            "dataSources": {
                "primary": "ds_mttr"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"open_outages\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How many of those have not come back yet. Guide: docs/data-health/dashboards.md, Daily state of health > Outages still open"
        },
        "viz_lic_pct": {
            "type": "splunk.singlevalue",
            "title": "Licence used yesterday (% of the daily quota)",
            "dataSources": {
                "primary": "ds_lic_pct"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"usage\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How close the instance came to its daily indexing limit. Guide: docs/data-health/dashboards.md, Daily state of health > Licence used yesterday (% of the daily quota)"
        },
        "viz_lic_days": {
            "type": "splunk.singlevalue",
            "title": "Days until the licence expires",
            "dataSources": {
                "primary": "ds_lic_days"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "When the Splunk licence runs out. Guide: docs/data-health/dashboards.md, Daily state of health > Days until the licence expires"
        },
        "viz_outages": {
            "type": "splunk.table",
            "title": "Outages in the last 24 h",
            "dataSources": {
                "primary": "ds_outages"
            },
            "options": {
                "count": 25
            },
            "description": "Each stretch of late or missing data, with how long it lasted. Guide: docs/data-health/dashboards.md, Daily state of health > Outages in the last 24 h"
        },
        "viz_flapping": {
            "type": "splunk.table",
            "title": "Flapping (3 or more status changes in 24 h)",
            "dataSources": {
                "primary": "ds_flapping"
            },
            "options": {
                "count": 25
            },
            "description": "Streams that keep stopping and starting. Guide: docs/data-health/dashboards.md, Daily state of health > Flapping (3 or more status changes in 24 h)"
        },
        "viz_never": {
            "type": "splunk.table",
            "title": "Never arrived, or a bad profile",
            "dataSources": {
                "primary": "ds_never"
            },
            "options": {
                "count": 25
            },
            "description": "Expected data that never came, and expected rows with a profile the app does not know. Guide: docs/data-health/dashboards.md, Daily state of health > Never arrived, or a bad profile"
        },
        "viz_unreg": {
            "type": "splunk.table",
            "title": "Unregistered: seen in the last 7 d but not expected",
            "dataSources": {
                "primary": "ds_unreg"
            },
            "options": {
                "count": 25
            },
            "description": "Data that arrives but that nobody listed as expected. Guide: docs/data-health/dashboards.md, Daily state of health > Unregistered: seen in the last 7 d but not expected"
        },
        "viz_fwd": {
            "type": "splunk.table",
            "title": "Forwarders: wrong version or disconnected",
            "dataSources": {
                "primary": "ds_fwd"
            },
            "options": {
                "count": 25
            },
            "description": "Splunk agents that need an upgrade or have stopped calling in. Guide: docs/data-health/dashboards.md, Daily state of health > Forwarders: wrong version or disconnected"
        },
        "viz_lag": {
            "type": "splunk.table",
            "title": "Slow arrival (lag p95 of 60 s or more)",
            "dataSources": {
                "primary": "ds_lag"
            },
            "options": {
                "count": 25
            },
            "description": "Data that arrives long after it was written. Guide: docs/data-health/dashboards.md, Daily state of health > Slow arrival (lag p95 of 60 s or more)"
        },
        "viz_volume": {
            "type": "splunk.table",
            "title": "Volume drops (24 h)",
            "dataSources": {
                "primary": "ds_volume"
            },
            "options": {
                "count": 25
            },
            "description": "Hours with far fewer events than usual. Guide: docs/data-health/dashboards.md, Daily state of health > Volume drops (24 h)"
        },
        "viz_skipped": {
            "type": "splunk.table",
            "title": "Skipped searches (24 h)",
            "dataSources": {
                "primary": "ds_skipped"
            },
            "options": {
                "count": 25
            },
            "description": "Background searches of this app that did not run on time. Guide: docs/data-health/dashboards.md, Daily state of health > Skipped searches (24 h)"
        },
        "viz_mutes": {
            "type": "splunk.table",
            "title": "Active and expiring mutes",
            "dataSources": {
                "primary": "ds_mutes"
            },
            "options": {
                "count": 25
            },
            "description": "What is muted now, and what unmutes within a day. Guide: docs/data-health/dashboards.md, Daily state of health > Active and expiring mutes"
        }
    },
    "layout": {
        "type": "grid",
        "options": {
            "width": 1440,
            "height": 1680
        },
        "structure": [
            {
                "item": "viz_when",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_outages_n",
                "type": "block",
                "position": {
                    "x": 240,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_open_n",
                "type": "block",
                "position": {
                    "x": 480,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_mttr",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_lic_pct",
                "type": "block",
                "position": {
                    "x": 960,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_lic_days",
                "type": "block",
                "position": {
                    "x": 1200,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_outages",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 120,
                    "w": 960,
                    "h": 340
                }
            },
            {
                "item": "viz_flapping",
                "type": "block",
                "position": {
                    "x": 960,
                    "y": 120,
                    "w": 480,
                    "h": 340
                }
            },
            {
                "item": "viz_never",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 460,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_fwd",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 460,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_unreg",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 760,
                    "w": 1440,
                    "h": 320
                }
            },
            {
                "item": "viz_lag",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 1080,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_volume",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 1080,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_skipped",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 1380,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_mutes",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 1380,
                    "w": 720,
                    "h": 300
                }
            }
        ]
    }
}
